questions.solution:
def flatten(items):
    flat = []
    for x in items:
        if isinstance(x, list):
            flat.extend(flatten(x))
        else:
            flat.append(x)
    return flat

questions.code:
def fib(n):
    return n if n < 2 else fib(n - 1) + fib(n - 2)

print([fib(i) for i in range(7)])

questions.solution:
def count_files(folder):
    total = len(folder["files"])
    for sub in folder["folders"]:
        total += count_files(sub)
    return total
